function rot13(str) {
  let decrypted = []
  str.toUpperCase().split('').forEach(function(el) {
    if (/^[A-Z]+$/.test(el)) {
      if ((el.charCodeAt() - 51) > 26) {
        decrypted.push(String.fromCharCode(el.charCodeAt() - 13))
      } else
        decrypted.push(String.fromCharCode(el.charCodeAt() + 13))
    } else decrypted.push(el)
  })
  return decrypted.join('')
}

